/**
 * Stateful in-memory D1 double for the shared-catalogue publish route.
 *
 * It implements only the statements generated by publish.ts and applies a
 * batch atomically: if any statement fails, the pre-batch state is restored.
 * `calls` records write statements (so assertions keep stable indexes) while
 * `reads` records SELECT statements such as the kind pre-check.
 */
function parseMetadata(value) {
  try {
    const parsed = JSON.parse(String(value));
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed;
  } catch {}
  return {};
}

export function createPublishD1({
  titles = [],
  episodes = [],
  failBatch = false,
  failOnSql = "",
} = {}) {
  const state = {
    titles: structuredClone(titles),
    episodes: structuredClone(episodes),
  };
  const calls = [];
  const reads = [];
  const batches = [];

  function query(sql, values) {
    if (/^SELECT kind, vip_exclusive, vip_early_access, public_at FROM catalog_titles WHERE id = \?$/i.test(sql)) {
      return state.titles
        .filter((title) => title.id === values[0])
        .map((title) => ({
          kind: title.kind,
          vip_exclusive: title.vip_exclusive ?? 0,
          vip_early_access: title.vip_early_access ?? 0,
          public_at: title.public_at ?? null,
        }));
    }
    if (/^SELECT kind FROM catalog_titles WHERE id = \?$/i.test(sql)) {
      return state.titles
        .filter((title) => title.id === values[0])
        .map((title) => ({ kind: title.kind }));
    }
    if (/^SELECT id FROM catalog_episodes WHERE title_id = \?$/i.test(sql)) {
      return state.episodes
        .filter((episode) => episode.title_id === values[0])
        .map((episode) => ({ id: episode.id }));
    }
    if (/^SELECT id FROM catalog_episodes WHERE title_id = \? AND season_number = \?$/i.test(sql)) {
      return state.episodes
        .filter((episode) => episode.title_id === values[0] && episode.season_number === values[1])
        .map((episode) => ({ id: episode.id }));
    }
    throw new Error(`Unexpected D1 query: ${sql}`);
  }

  function apply(sql, values) {
    if (/^INSERT INTO catalog_titles/i.test(sql)) {
      const [id, kind, title, overview, releaseDate, posterPath, backdropPath, genresJson, metadataJson, vipExclusive, vipEarlyAccess, publicAt] = values;
      const hasVip = values.length > 9;
      const existing = state.titles.find((entry) => entry.id === id);
      if (existing) {
        existing.kind = kind;
        existing.title = title;
        existing.overview = overview;
        existing.release_date = releaseDate;
        existing.poster_path = posterPath;
        existing.backdrop_path = backdropPath;
        existing.genres_json = genresJson;
        existing.metadata_json = JSON.stringify({
          ...parseMetadata(existing.metadata_json),
          ...parseMetadata(metadataJson),
        });
        if (hasVip) {
          existing.vip_exclusive = vipExclusive;
          existing.vip_early_access = vipEarlyAccess;
          existing.public_at = publicAt;
        }
        existing.published = 1;
        existing.updated_at = "2024-01-01T00:00:00Z";
      } else {
        state.titles.push({
          id,
          kind,
          title,
          overview,
          release_date: releaseDate,
          poster_path: posterPath,
          backdrop_path: backdropPath,
          genres_json: genresJson,
          metadata_json: metadataJson,
          published: 1,
          updated_at: "2024-01-01T00:00:00Z",
          ...(hasVip ? { vip_exclusive: vipExclusive, vip_early_access: vipEarlyAccess, public_at: publicAt } : {}),
        });
      }
      return { success: true, meta: { changes: 1 } };
    }

    if (/^INSERT INTO catalog_episodes/i.test(sql)) {
      const [id, titleId, seasonNumber, episodeNumber, title, overview, durationSeconds, thumbnailPath, metadataJson] = values;
      const existing = state.episodes.find((entry) => entry.id === id);
      if (existing) {
        existing.title = title;
        existing.overview = overview;
        existing.duration_seconds = durationSeconds;
        existing.thumbnail_path = thumbnailPath;
        existing.metadata_json = metadataJson;
        existing.updated_at = "2024-01-01T00:00:00Z";
      } else {
        state.episodes.push({
          id,
          title_id: titleId,
          season_number: seasonNumber,
          episode_number: episodeNumber,
          title,
          overview,
          duration_seconds: durationSeconds,
          stream_uid: null,
          thumbnail_path: thumbnailPath,
          metadata_json: metadataJson,
          updated_at: "2024-01-01T00:00:00Z",
        });
      }
      return { success: true, meta: { changes: 1 } };
    }

    if (/^DELETE FROM catalog_episodes/i.test(sql)) {
      const titleId = values[0];
      const seasonScoped = /season_number = \?/i.test(sql);
      const idScoped = /AND id = \?$/i.test(sql.trim());
      if (!idScoped) throw new Error(`Unexpected unscoped DELETE: ${sql}`);
      const seasonNumber = seasonScoped ? values[1] : null;
      const episodeId = seasonScoped ? values[2] : values[1];
      const before = state.episodes.length;
      state.episodes = state.episodes.filter((episode) => {
        if (episode.title_id !== titleId) return true;
        if (seasonNumber !== null && episode.season_number !== seasonNumber) return true;
        return episode.id !== episodeId;
      });
      return { success: true, meta: { changes: before - state.episodes.length } };
    }

    throw new Error(`Unexpected D1 statement: ${sql}`);
  }

  function prepare(sql) {
    const call = { sql, values: [] };
    const isRead = /^\s*SELECT\b/i.test(sql);
    (isRead ? reads : calls).push(call);
    const statement = {
      __call: call,
      bind(...values) {
        call.values = values;
        return statement;
      },
      async all() {
        return { success: true, results: query(sql, call.values) };
      },
      async run() {
        return apply(sql, call.values);
      },
      get sql() {
        return sql;
      },
      get values() {
        return call.values;
      },
    };
    return statement;
  }

  return {
    state,
    calls,
    reads,
    batches,
    prepare,
    async batch(statements) {
      batches.push(statements.map((statement) => ({
        sql: statement.sql,
        values: [...statement.values],
      })));
      if (failBatch) throw new Error("D1 batch failed");

      const snapshot = {
        titles: structuredClone(state.titles),
        episodes: structuredClone(state.episodes),
      };
      const results = [];
      try {
        for (const statement of statements) {
          const call = statement.__call || { sql: statement.sql, values: statement.values };
          if (failOnSql && call.sql.includes(failOnSql)) {
            throw new Error(`D1 statement failed: ${call.sql}`);
          }
          results.push(apply(call.sql, call.values));
        }
      } catch (error) {
        state.titles = snapshot.titles;
        state.episodes = snapshot.episodes;
        throw error;
      }
      return results;
    },
  };
}
